import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let S be the set of points (x, y) with 0 < x <= 1 and 0 < y <= 1 such that, writing N(x) = floor(log_{base_a}(1/x)) and M(y) = floor(log_{base_b}(1/y)), the congruence N(x) + M(y) ≡ {residue_r} (mod {modulus_t}) holds. If the area of S is m/n in lowest terms, determine m + n. Here log_k denotes the logarithm base k and floor denotes the greatest integer less than or equal to its argument.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Produces parameters for a coupled-floor-logarithm area problem.
# The generator retries to satisfy difficulty constraints.
from fractions import Fraction

def area_fraction(a, b, t, r):
    u = Fraction(1, a)
    v = Fraction(1, b)
    # A = (a-1)(b-1) * sum_{n,m>=0, n+m≡r (mod t)} u^{n+1} v^{m+1}
    if u != v:
        num_common = Fraction((a - 1) * (b - 1), 1) * u * v
        term = (v ** (r + 1)) / (1 - v ** t) - (u ** (r + 1)) / (1 - u ** t)
        A = num_common * term / (v - u)
    else:
        # a == b case: closed form via weighted geometric series
        # A = (a-1)^2 * u^{r+2} * [ (r+1)/(1 - u^t) + t*u^t/(1 - u^t)^2 ]
        A = Fraction((a - 1) ** 2, 1) * (u ** (r + 2)) * (
            Fraction(r + 1, 1) / (1 - u ** t) + Fraction(t, 1) * (u ** t) / ((1 - u ** t) ** 2)
        )
    return A

attempts = 0
while True:
    attempts += 1
    a = rng.randint(2, 12)
    b = rng.randint(2, 12)
    t = rng.randint(2, 6)
    r = rng.randint(0, t - 1)
    # Avoid too symmetric triviality occasionally by nudging parameters
    if attempts % 11 == 0 and a == b and t == 2:
        t = rng.randint(3, 6)
        r = rng.randint(0, t - 1)
    A = area_fraction(a, b, t, r)
    # Basic validity: area in (0,1)
    if A <= 0 or A >= 1:
        continue
    den = A.denominator
    # Difficulty gate: ensure denominators are not tiny, avoiding trivial sums
    if den > 120:
        return {
            'base_a': a,
            'base_b': b,
            'modulus_t': t,
            'residue_r': r
        }
    if attempts > 2000:
        # Fallback to a known nontrivial instance
        a, b, t, r = 3, 7, 5, 2
        A = area_fraction(a, b, t, r)
        return {
            'base_a': a,
            'base_b': b,
            'modulus_t': t,
            'residue_r': r
        }

