from fractions import Fraction

# Validate presence and types
for key in ['base_a', 'base_b', 'modulus_t', 'residue_r']:
    if key not in assign:
        # Missing parameter
        return (False, None)
    if not isinstance(assign[key], int):
        return (False, None)

a = assign['base_a']
b = assign['base_b']
t = assign['modulus_t']
r = assign['residue_r']

# Domain checks
if a < 2 or b < 2:
    return (False, None)  # invalid bases
if t < 2:
    return (False, None)  # modulus must be >= 2
if r < 0 or r >= t:
    return (False, None)  # invalid residue

# Compute area via closed-form sums
u = Fraction(1, a)
v = Fraction(1, b)
if u != v:
    num_common = Fraction((a - 1) * (b - 1), 1) * u * v
    term = (v ** (r + 1)) / (1 - v ** t) - (u ** (r + 1)) / (1 - u ** t)
    A = num_common * term / (v - u)
else:
