        Fraction(r + 1, 1) / (1 - u ** t) + Fraction(t, 1) * (u ** t) / ((1 - u ** t) ** 2)
    )

# Sanity checks
if not (A > 0 and A < 1):
    return (False, None)  # area must be in (0,1)

# Enforce non-triviality/difficulty: denominator should be reasonably large
